import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long h = nextLong();
        long[] cap = new long[n], opt = new long[n];
        for (int i = 0; i < n; i++) cap[i] = h - nextLong(); // room left beside each mandatory task
        for (int i = 0; i < n; i++) opt[i] = nextLong();
        Arrays.sort(cap);
        Arrays.sort(opt);
        // Smallest optional task goes to the smallest capacity that holds it.
        int j = 0;
        for (long c : cap)
            if (j < n && opt[j] <= c) j++;
        System.out.println(j);
    }
}

